(async () => {
  const page = document.querySelector('@selector/pages.presets');
  const settle = () => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  const input = async (element, value) => { if (!element) throw new Error('Customize input missing'); const prototype = element.tagName === 'SELECT' ? HTMLSelectElement.prototype : HTMLInputElement.prototype; Object.getOwnPropertyDescriptor(prototype, 'value').set.call(element, value); element.dispatchEvent(new Event('input', { bubbles: true })); element.dispatchEvent(new Event('change', { bubbles: true })); await settle(); };
  const saveDraft = async () => { const actions = page.querySelector('@selector/lightDesk.presetActions'); const button = actions?.querySelector('button'); if (!button || button.disabled) throw new Error('Save draft unavailable'); button.click(); await settle(); };
  const effects = [...page.querySelectorAll('select')];
  if (effects.length !== 2) throw new Error('Both physical activity bands must be editable');
  const originalBusy = effects[1].value;
  await input(effects[0], '');
  await input(page.querySelector('input[type="number"]'), '120');
  const ranges = [...page.querySelectorAll('input[type="range"]')];
  await input(ranges[ranges.length - 1], '0');
  const checkboxes = [...page.querySelectorAll('input[type="checkbox"]')];
  const previewMotion = checkboxes[checkboxes.length - 1];
  if (!previewMotion) throw new Error('Browser-only reduced-motion choice missing');
  if (previewMotion.checked) { previewMotion.click(); await settle(); }
  await saveDraft();
  const combined = JSON.parse(localStorage.getItem('lighting-control.preset-drafts.v1') || '{}')['5'];
  const loadButton = [...page.querySelectorAll('button')].find((button) => button.querySelector('strong')?.textContent.trim() === 'Load');
  if (!loadButton) throw new Error('Load preset selection missing');
  loadButton.click(); await settle();
  const details = page.querySelector('details'); if (!details) throw new Error('Load threshold controls missing'); details.open = true;
  const numbers = [...page.querySelectorAll('input[type="number"]')];
  if (numbers.length !== 4) throw new Error('Freshness and all load thresholds must be editable');
  await input(numbers[1], '75'); await input(numbers[2], '55'); await input(numbers[3], '12');
  await saveDraft();
  const drafts = JSON.parse(localStorage.getItem('lighting-control.preset-drafts.v1') || '{}');
  const load = drafts['2'];
  const combinedButton = [...page.querySelectorAll('button')].find((button) => button.querySelector('strong')?.textContent.trim() === 'Combined');
  combinedButton.click(); await settle();
  const restored = [...page.querySelectorAll('select')];
  const clear = combined?.activity?.activeEffectId === '' && combined.activity.busyEffectId === originalBusy && combined.guardrails.sourceMaxAgeSeconds === 120 && combined.guardrails.staleFallbackBrightnessPercent === 0 && combined.respectReducedMotion === false && load?.guardrails?.loadEnterPercent === 75 && load.guardrails.loadExitPercent === 55 && load.guardrails.debounceSeconds === 12 && restored[0]?.value === '' && restored[1]?.value === originalBusy && page.querySelector('input[type="number"]')?.value === '120';
  page.dataset.lightdeskCustomizeDraftClear = String(clear);
  return { clear, combined, load, restoredPhysicalEffects: restored.map((select) => select.value) };
})()
